package com.vandorlabs.neoforge.copifier;
import com.google.gson.*;
import com.vandorlabs.neoforge.door.*;
import java.nio.file.*;
import java.util.*;
import java.util.zip.GZIPInputStream;
import net.minecraft.core.*;
import net.minecraft.core.registries.BuiltInRegistries;
import net.minecraft.nbt.*;
import net.minecraft.resources.ResourceLocation;
import net.minecraft.server.level.*;
import net.minecraft.world.level.GameType;
import net.minecraft.world.level.block.Blocks;
import net.minecraft.world.level.block.state.properties.DoubleBlockHalf;
import net.neoforged.bus.api.SubscribeEvent;
import net.neoforged.fml.common.EventBusSubscriber;
import net.neoforged.neoforge.event.server.ServerStartedEvent;
/** Installed ordinary Door owner resolution, Source callbacks and settings-only history. */
@EventBusSubscriber(modid="vandorlabs")
public final class NativeCopifierDoorWorldChecks {
 private static final BlockPos POS=new BlockPos(15840,100,14640);private static int checks;
 private static void need(boolean yes,String why){checks++;if(!yes)throw new AssertionError("Copied Door world: "+why);}
 private static NativeProgrammableDoorEntity put(ServerLevel level,String id,Direction facing,CompoundTag data){
  level.getChunkAt(POS);level.setBlock(POS,Blocks.AIR.defaultBlockState(),18);level.setBlock(POS.above(),Blocks.AIR.defaultBlockState(),18);level.setBlock(POS.below(),Blocks.STONE.defaultBlockState(),18);var block=(NativeOrdinaryDoorBlock)BuiltInRegistries.BLOCK.get(ResourceLocation.fromNamespaceAndPath("vandorlabs",id));var state=block.defaultBlockState().setValue(NativeProgrammableDoorBlock.FACING,facing).setValue(NativeProgrammableDoorBlock.HALF,DoubleBlockHalf.LOWER);level.setBlock(POS,state,18);level.setBlock(POS.above(),state.setValue(NativeProgrammableDoorBlock.HALF,DoubleBlockHalf.UPPER),18);var tile=(NativeProgrammableDoorEntity)level.getBlockEntity(POS);var input=data.copy();input.putString("UnrelatedDoorMarker","retained");tile.loadWithComponents(input,level.registryAccess());return tile;
 }
 private static void write(ServerLevel level)throws Exception{byte[] raw;try(var in=new GZIPInputStream(Files.newInputStream(Path.of(System.getProperty("vandorlabs.copifierDoorReference"))))){raw=in.readAllBytes();}var actor=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,1881),"CopiedDoors"));actor.setGameMode(GameType.SURVIVAL);actor.setPos(POS.getX()+.5,POS.getY()+1,POS.getZ()-2);int captures=0,cases=0;
  for(var element:JsonParser.parseString(new String(raw,java.nio.charset.StandardCharsets.UTF_8)).getAsJsonArray()){
   var row=element.getAsJsonObject();String id=row.get("id").getAsString();Direction facing=Direction.from3DDataValue(row.get("facing").getAsInt());if(row.has("input")){put(level,id,facing,TagParser.parseTag(row.get("input").getAsString()));var expected=TagParser.parseTag(row.get("capture").getAsString());var actual=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);need(expected.equals(actual),"Source capture case="+captures+" expected="+expected+" actual="+actual);need(expected.equals(NativeCopifierHousingWorld.capture(level,POS.above(),actor,Direction.NORTH)),"upper capture resolves lower");captures++;}
   var owner=put(level,id,facing.getOpposite(),TagParser.parseTag(row.get("target").getAsString()));var values=TagParser.parseTag(row.get("values").getAsString());var immutable=values.copy();var before=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);NativeCopifierUndo.begin(actor,level);boolean applied;try{applied=NativeCopifierHousingWorld.applySingle(level,POS.above(),actor,Direction.NORTH,values);}finally{NativeCopifierUndo.finish(actor);}var expected=TagParser.parseTag(row.get("after").getAsString());var actual=NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH);need(applied==row.get("applied").getAsBoolean(),"Source result case="+cases);need(expected.equals(actual),"Source apply case="+cases+" values="+values+" expected="+expected+" actual="+actual);need(level.getBlockEntity(POS)==owner&&owner.getBlockState().getValue(NativeProgrammableDoorBlock.FACING)==facing.getOpposite(),"same logical owner and placement facing");need(owner.saveWithoutMetadata(level.registryAccess()).getString("UnrelatedDoorMarker").equals("retained")&&values.equals(immutable),"opaque owner fields and clipboard retained");
   if(applied&&!before.equals(actual)){need(NativeCopifierUndo.undo(actor),"logical lower undo case="+cases);need(TagParser.parseTag(row.get("undo").getAsString()).equals(NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH)),"Source undo projection case="+cases);}cases++;
  }
  connected(level,actor);privateStateAndRefusals(level,actor);put(level,"programmable_door",Direction.NORTH,new CompoundTag());var values=new CompoundTag();values.putInt("door_face_texture",7);need(NativeCopifierHousingWorld.applySingle(level,POS.above(),actor,Direction.NORTH,values),"saved upper-cell artwork edit");System.out.println("[vandorlabs][copifier-door] write PASS captures="+captures+" cases="+cases+" checks="+checks);
 }
 private static void connected(ServerLevel level,ServerPlayer actor){var first=put(level,"programmable_door",Direction.NORTH,new CompoundTag());var peer=POS.east(1);var state=first.getBlockState();level.setBlock(peer.below(),Blocks.STONE.defaultBlockState(),18);level.setBlock(peer,state,18);level.setBlock(peer.above(),state.setValue(NativeProgrammableDoorBlock.HALF,DoubleBlockHalf.UPPER),18);var second=(NativeProgrammableDoorEntity)level.getBlockEntity(peer);second.loadWithComponents(new CompoundTag(),level.registryAccess());first.copiedState();second.copiedState();var values=new CompoundTag();values.putInt("door_face_texture",7);NativeCopifierUndo.begin(actor,level);int count;try{count=NativeCopifierHousingConnected.apply(level,POS.above(),actor,Direction.NORTH,values,false);}finally{NativeCopifierUndo.finish(actor);}need(count==2,"four physical cells select two logical owners count="+count);need(first.settings().faceTexture()==7&&second.settings().faceTexture()==7,"connected logical roots updated");need(NativeCopifierUndo.undo(actor)&&first.settings().faceTexture()==-1&&second.settings().faceTexture()==-1,"connected lower-root undo");level.setBlock(peer,Blocks.AIR.defaultBlockState(),18);level.setBlock(peer.above(),Blocks.AIR.defaultBlockState(),18);}
 private static void privateStateAndRefusals(ServerLevel level,ServerPlayer actor){
  var owner=put(level,"programmable_door",Direction.NORTH,new CompoundTag());owner.copiedState();var saved=owner.saveWithoutMetadata(level.registryAccess());saved.putInt("DoorSecurityMode",2);saved.putInt("DoorPanelMode",1);saved.putBoolean("SpaceDoorPanel",true);var legacy=new CompoundTag();legacy.putString("id","vandorlabs:access_card");legacy.putByte("Count",(byte)1);legacy.putShort("Damage",(short)2);var payload=new CompoundTag();payload.putString("OldCredentialMarker","retained");legacy.put("tag",payload.copy());legacy.put("ForgeCaps",payload.copy());var reader=new CompoundTag();reader.putBoolean("AnyToken",true);reader.putInt("AllowedTokens",127);reader.putInt("TokenBehavior",0);reader.put("InsertedToken",legacy);saved.put("DoorKeyReader",reader);owner.loadWithComponents(saved,level.registryAccess());var token=owner.credentialRecovery(level.registryAccess()).getCompound("DoorKeyReader").getCompound("InsertedToken").copy();need(!token.isEmpty(),"actual previous-version credential installed");
  var values=new CompoundTag();values.putInt("door_face_texture",7);var security=new CompoundTag();security.putInt("Mode",4);security.putInt("Allowed",127);values.put("door_security",security);values.put("DoorKeyReader",new CompoundTag());NativeCopifierUndo.begin(actor,level);try{need(NativeCopifierHousingWorld.applySingle(level,POS.above(),actor,Direction.NORTH,values),"copy appearance/security with existing private credential");}finally{NativeCopifierUndo.finish(actor);}need(owner.credentialRecovery(level.registryAccess()).getCompound("DoorKeyReader").getCompound("InsertedToken").equals(token),"copy preserves complete old credential payload");need(!NativeCopifierHousingWorld.capture(level,POS,actor,Direction.NORTH).toString().contains("InsertedToken"),"clipboard omits physical credentials");need(NativeCopifierUndo.undo(actor)&&owner.credentialRecovery(level.registryAccess()).getCompound("DoorKeyReader").getCompound("InsertedToken").equals(token),"undo preserves one old credential owner");
  var denied=new net.neoforged.neoforge.common.util.FakePlayer(level,new com.mojang.authlib.GameProfile(new UUID(0,1882),"DeniedDoorRoot")){@Override public boolean mayUseItemAt(BlockPos pos,Direction face,net.minecraft.world.item.ItemStack item){return !pos.equals(POS)&&super.mayUseItemAt(pos,face,item);}};denied.setGameMode(GameType.SURVIVAL);denied.setPos(actor.position());var before=owner.saveWithoutMetadata(level.registryAccess());need(NativeCopifierHousingWorld.capture(level,POS.above(),denied,Direction.NORTH)==null&&!NativeCopifierHousingWorld.applySingle(level,POS.above(),denied,Direction.NORTH,values)&&before.equals(owner.saveWithoutMetadata(level.registryAccess())),"upper access cannot bypass protected lower owner");need(!java.util.concurrent.CompletableFuture.supplyAsync(()->owner.configureCopied(values)).join()&&before.equals(owner.saveWithoutMetadata(level.registryAccess())),"worker refused before world/ownership mutation");
  var recovery=before.copy();recovery.putBoolean("DoorPlacementRecovery",true);owner.loadWithComponents(recovery,level.registryAccess());need(NativeCopifierHousingWorld.capture(level,POS.above(),actor,Direction.NORTH)==null&&!owner.configureCopied(values),"placement recovery stays inert to copying");var replacement=put(level,"programmable_door",Direction.NORTH,new CompoundTag());need(!owner.configureCopied(values)&&level.getBlockEntity(POS)==replacement,"stale owner cannot edit replacement");
 }
 private static void read(ServerLevel level){level.getChunkAt(POS);need(level.getBlockEntity(POS) instanceof NativeProgrammableDoorEntity,"saved lower owner");var owner=(NativeProgrammableDoorEntity)level.getBlockEntity(POS);need(owner.settings().faceTexture()==7&&owner.saveWithoutMetadata(level.registryAccess()).getString("UnrelatedDoorMarker").equals("retained"),"copied artwork and opaque state survive restart");need(NativeDoorLifecycle.complete(level,POS,(NativeProgrammableDoorBlock)owner.getBlockState().getBlock()),"saved upper structure complete");System.out.println("[vandorlabs][copifier-door] read PASS checks="+checks);}
 @SubscribeEvent public static void started(ServerStartedEvent event){String phase=System.getProperty("vandorlabs.transmitterPhase","");if(!phase.equals("copifier-door-write")&&!phase.equals("copifier-door-read"))return;try{if(phase.endsWith("write"))write(event.getServer().overworld());else read(event.getServer().overworld());event.getServer().saveEverything(true,true,true);}catch(Throwable failure){failure.printStackTrace();System.out.println("[vandorlabs][copifier-door] FAIL "+failure);}finally{event.getServer().halt(false);}}
}
